#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    std::string processString(std::string s, std::vector<std::vector<std::string>>& operations) {
        for (const auto& op : operations) {
            const std::string& cmd = op[0];
            if (cmd == "REVERSE") {
                int l = std::stoi(op[1]), r = std::stoi(op[2]);
                std::reverse(s.begin() + l, s.begin() + r + 1);
            } else if (cmd == "REPLACE") {
                int idx = std::stoi(op[1]);
                s[idx] = op[2][0];
            } else if (cmd == "SWAP") {
                int i = std::stoi(op[1]), j = std::stoi(op[2]);
                std::swap(s[i], s[j]);
            }
        }
        return s;
    }
};

import java.util.*;

class Solution {
    public String processString(String s, String[][] operations) {
        char[] arr = s.toCharArray();
        for (String[] op : operations) {
            String cmd = op[0];
            if (cmd.equals("REVERSE")) {
                int l = Integer.parseInt(op[1]), r = Integer.parseInt(op[2]);
                while (l < r) {
                    char t = arr[l];
                    arr[l] = arr[r];
                    arr[r] = t;
                    l++;
                    r--;
                }
            } else if (cmd.equals("REPLACE")) {
                int idx = Integer.parseInt(op[1]);
                arr[idx] = op[2].charAt(0);
            } else if (cmd.equals("SWAP")) {
                int i = Integer.parseInt(op[1]), j = Integer.parseInt(op[2]);
                char t = arr[i];
                arr[i] = arr[j];
                arr[j] = t;
            }
        }
        return new String(arr);
    }
}

