    const arr = s.split("");
    for (const op of operations) {
        const cmd = op[0];
        if (cmd === "REVERSE") {
            let l = parseInt(op[1]), r = parseInt(op[2]);
            while (l < r) {
                const t = arr[l];
                arr[l] = arr[r];
                arr[r] = t;
                l++;
                r--;
            }
        } else if (cmd === "REPLACE") {
            const idx = parseInt(op[1]);
            arr[idx] = op[2];
        } else if (cmd === "SWAP") {
